<?php
require_once __DIR__ . '/../config/Database.php';
require_once __DIR__ . '/JurnalKas.php';
class Penerimaan {
 private PDO $db; public function __construct(){ $this->db=Database::connect(); }
 public function getAll(): array { return $this->db->query('SELECT p.*,d.nama AS donatur,k.nama AS kategori,k.pos_dana FROM penerimaan p JOIN donatur d ON d.id=p.donatur_id JOIN kategori_dana k ON k.id=p.kategori_id ORDER BY p.tanggal DESC,p.id DESC')->fetchAll(); }
 public function getById(int $id){$s=$this->db->prepare('SELECT * FROM penerimaan WHERE id=?');$s->execute([$id]);return $s->fetch();}
 public function getReceipt(int $id){$s=$this->db->prepare('SELECT p.*,d.kode AS kode_donatur,d.nama AS donatur,d.jenis,d.telepon,d.alamat,k.nama AS kategori,k.pos_dana FROM penerimaan p JOIN donatur d ON d.id=p.donatur_id JOIN kategori_dana k ON k.id=p.kategori_id WHERE p.id=?');$s->execute([$id]);return $s->fetch();}
 public function getDonatur(): array{return $this->db->query('SELECT id,nama FROM donatur ORDER BY nama')->fetchAll();}
 public function getKategori(): array{return $this->db->query('SELECT id,nama,pos_dana FROM kategori_dana ORDER BY nama')->fetchAll();}
 private function syncJournal(int $id,array $d,string $no): void { $q=$this->db->prepare('SELECT pos_dana FROM kategori_dana WHERE id=?');$q->execute([$d['kategori_id']]);$pos=$q->fetchColumn();if(!$pos)throw new RuntimeException('Kategori dana tidak ditemukan.');
 $ket='Penerimaan '.$no.($d['keterangan']?' - '.$d['keterangan']:'');
 $find=$this->db->prepare("SELECT id FROM jurnal_kas WHERE sumber='penerimaan' AND ref_id=? ORDER BY id DESC LIMIT 1");$find->execute([$id]);$journalId=$find->fetchColumn();
 if($journalId){$s=$this->db->prepare("UPDATE jurnal_kas SET tanggal=?,pos_dana=?,nominal=?,keterangan=?,jenis='masuk' WHERE sumber='penerimaan' AND ref_id=?");$s->execute([$d['tanggal'],$pos,$d['nominal'],$ket,$id]);}
 else{(new JurnalKas())->catat(['tanggal'=>$d['tanggal'],'jenis'=>'masuk','pos_dana'=>$pos,'nominal'=>$d['nominal'],'keterangan'=>$ket,'sumber'=>'penerimaan','ref_id'=>$id]);}
 }
 public function create(array $d): int { $this->db->beginTransaction();try{$q=$this->db->prepare('SELECT pos_dana FROM kategori_dana WHERE id=?');$q->execute([$d['kategori_id']]);$pos=$q->fetchColumn();if(!$pos)throw new RuntimeException('Kategori dana tidak ditemukan.');$prefix='KWT-'.date('Y',strtotime($d['tanggal'])).'-';$q=$this->db->prepare('SELECT COALESCE(MAX(CAST(SUBSTRING(no_kuitansi,10) AS UNSIGNED)),0) FROM penerimaan WHERE no_kuitansi LIKE ?');$q->execute([$prefix.'%']);$next=(int)$q->fetchColumn()+1;$no=$prefix.str_pad((string)$next,4,'0',STR_PAD_LEFT);$check=$this->db->prepare('SELECT 1 FROM penerimaan WHERE no_kuitansi=? LIMIT 1');while(true){$check->execute([$no]);if(!$check->fetchColumn())break;$next++;$no=$prefix.str_pad((string)$next,4,'0',STR_PAD_LEFT);}$s=$this->db->prepare('INSERT INTO penerimaan(no_kuitansi,tanggal,donatur_id,kategori_id,nominal,keterangan) VALUES(?,?,?,?,?,?)');$s->execute([$no,$d['tanggal'],$d['donatur_id'],$d['kategori_id'],$d['nominal'],$d['keterangan']]);$id=(int)$this->db->lastInsertId();(new JurnalKas())->catat(['tanggal'=>$d['tanggal'],'jenis'=>'masuk','pos_dana'=>$pos,'nominal'=>$d['nominal'],'keterangan'=>'Penerimaan '.$no.($d['keterangan']?' - '.$d['keterangan']:''),'sumber'=>'penerimaan','ref_id'=>$id]);$this->db->commit();return $id;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;} }
 public function update(int $id,array $d): void { $this->db->beginTransaction();try{$old=$this->getById($id);if(!$old)throw new RuntimeException('Penerimaan tidak ditemukan.');$s=$this->db->prepare('UPDATE penerimaan SET tanggal=?,donatur_id=?,kategori_id=?,nominal=?,keterangan=? WHERE id=?');$s->execute([$d['tanggal'],$d['donatur_id'],$d['kategori_id'],$d['nominal'],$d['keterangan'],$id]);$this->syncJournal($id,$d,$old['no_kuitansi']);$this->checkBalances();$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;} }
 public function delete(int $id): void { $this->db->beginTransaction();try{$old=$this->getById($id);if(!$old)throw new RuntimeException('Penerimaan tidak ditemukan.');$this->db->prepare("DELETE FROM jurnal_kas WHERE sumber='penerimaan' AND ref_id=?")->execute([$id]);$this->db->prepare('DELETE FROM penerimaan WHERE id=?')->execute([$id]);$this->checkBalances();$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;} }
 private function checkBalances(): void {foreach(JurnalKas::POS as $pos=>$name){$s=$this->db->prepare("SELECT COALESCE(SUM(CASE WHEN jenis='masuk' THEN nominal ELSE -nominal END),0) FROM jurnal_kas WHERE pos_dana=?");$s->execute([$pos]);if((float)$s->fetchColumn()<0)throw new RuntimeException('Perubahan ditolak karena saldo '.$name.' akan menjadi minus.');}}
}
